function ensureFiChecklistStates(t){let route=routeFor(t),old=t.fiChecklistStates||{};t.fiChecklistStates={};route.forEach(([code,name])=>{let v=old[code];t.fiChecklistStates[code]=FI_VISUAL_STATUSES.includes(v)?v:'Not Started'});return t.fiChecklistStates}
