function ensureLeadTasks(t){if(!Array.isArray(t.leadTasks)||!t.leadTasks.length){t.leadTasks=defaultLeadTasks()}else{let by=new Map(t.leadTasks.map(x=>[x.name,x]));t.leadTasks=LEAD_TASKS.map((name,i)=>Object.assign({name,status:/customer source/i.test(name)?'Requirement TBD':'Not Started',order:i+1,notes:''},by.get(name)||{}))}return t.leadTasks}
function applyLeadBaseline(t,taskName){ensureLeadTasks(t);let idx=LEAD_TASKS.indexOf(taskName);t.currentLeadTask=taskName||'';if(idx<0){t.leadProgress=0;return}for(let i=0;i<t.leadTasks.length;i++){let x=t.leadTasks[i];if(x.status==='N/A'||x.status==='Requirement TBD')continue;if(i<idx)x.status='Complete';else if(i===idx)x.status='In Progress';else x.status='Not Started'}t.leadProgress=leadProgress(t)}
