function leadProgress(t){let tasks=ensureLeadTasks(t),app=tasks.filter(x=>x.status!=='N/A');if(app.length&&app.every(x=>x.status==='Complete'))return 100;let idx=LEAD_TASKS.indexOf(t.currentLeadTask);if(idx<0)return 0;let before=tasks.slice(0,idx).filter(x=>x.status!=='N/A').length,den=app.length||LEAD_TASKS.length;return Math.round(before/den*100)}
function nextLeadTasks(t,n=5){let r=leadRemaining(t),out=[];let add=x=>{if(x&&!out.includes(x))out.push(x)};r.filter(x=>x.status==='In Progress').forEach(add);add(r.find(x=>x.name===t.currentLeadTask));r.filter(x=>x.status==='Requirement TBD').forEach(add);r.filter(x=>x.status==='Not Started').forEach(add);return out.slice(0,n)}
