function scenario(){let s=blank();s.environment='SCENARIO TEST';let data=[['1450071','Regera','R900','Intel','FI','R9xx_170_10','R9xx_150_10','2026-09-02'],['1450073','Celestiq','R915t','SK Hynix','FI','R91x_160_30','R91x_170_10','2026-08-28'],['1350660','Targa','2955t','TSMC','Packing',FI200,'FI_190_050','2026-09-07'],['1350627','Panamera','2935','Hangzhou','OI','FI_130_010','FI_150_010','2026-12-22'],['BX1001','Boxster','2915S2','Customer A','Shipped',FI200,FI200,'2026-08-20'],['MC1001','Macan','2935XR','Customer B','FI','FI_180_040','FI_160_040','2026-09-15']];s.tools=data.map(d=>{let t=defaultTool();Object.assign(t,{id:d[0],codename:d[1],model:d[2],customer:d[3],toolStatus:d[4],currentChecklist:d[5],microSchedule:d[6],shipDate:d[7],family:'29XX',latestStatus:d[4]==='Packing'?'Packing the system.':'Progressing with FI testing.',lamp:Math.floor(Math.random()*500)+20});let rr=routeFor(t),oi=checklistIndex(t,t.currentChecklist);ensureFiChecklistStates(t);rr.forEach(([c],i)=>{if(i<oi)t.fiChecklistStates[c]='Complete';else if(i===oi)t.fiChecklistStates[c]=d[4]==='Shipped'?'Complete':'In Progress'});if(d[4]==='Shipped'){t.shipping.scheduleStatus='Complete';rr.forEach(([c])=>t.fiChecklistStates[c]='Complete')}return t});s.tools[1].ncs=[{id:'NC#73',description:'IP Cal failing — IlluminationProfileAverageGain',state:'Escalated',days:1,blocking:true,poa:'Perform latest approved POA',owner:'Engineering',opened:'2026-08-26'}];s.priorities.weekday=s.tools.filter(t=>t.toolStatus!=='Shipped').map((t,i)=>({tool:t.id,priority:i+1,assignment:t.driver,notes:'Continue progressing'}));return s}
