function exportData(){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`B7-FI-V3-${state.environment.replaceAll(' ','-')}-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function screenshotReportTitle(){let date=fmtDate(today());if(route.center==='status')return `${route.sub==='weekend'?'WEEKEND':'WEEKDAY'} MORNING STATUS · ${date}`;if(route.center==='shipping')return `${state.quarter} SHIPPING SCHEDULE · ${date}`;if(route.center==='priority')return `${route.sub==='weekend'?'WEEKEND':'WEEKDAY'} PRIORITIES · ${date}`;if(route.center==='action')return `ACTION CENTER · ${date}`;if(route.center==='reference')return `REFERENCE LIBRARY · ${date}`;if(route.center==='archive')return `ARCHIVE · ${date}`;if(route.center==='search')return `SEARCH · ${date}`;if(route.center==='meeting')return `MEETINGS · ${date}`;if(route.center==='update')return `${route.sub==='daily'?'COMMAND CENTER DAILY UPDATE':'UPDATE'} · ${date}`;if(route.center==='operations'){if(route.sub==='tools'||route.sub==='tool')return `TOOLS · ${date}`;if(route.sub==='daily')return `COMMAND CENTER DAILY UPDATE · ${date}`;if(route.sub==='archive')return `ARCHIVE · ${date}`;return `LIVE OPERATIONS · ${date}`;}return `${String(route.center||'COMMAND CENTER').toUpperCase()} · ${date}`}
function screenshot(){if(document.body.classList.contains('presentation-mode'))exitPresentation();screenshotRestore={livePaused,snapshotPaused};livePaused=true;snapshotPaused=true;document.body.classList.add('screenshot-mode');let x=document.querySelector('#exitScreenshot');x.textContent='×';x.setAttribute('aria-label','Exit screenshot mode');x.title='Exit screenshot mode';x.classList.remove('hidden');window.scrollTo(0,0);render()}
function exitScreenshot(){document.body.classList.remove('screenshot-mode');if(screenshotRestore){livePaused=!!screenshotRestore.livePaused;snapshotPaused=!!screenshotRestore.snapshotPaused;screenshotRestore=null}document.querySelector('#exitScreenshot').classList.add('hidden');document.querySelector('#screenshotReportTitle')?.remove();render()}
function fitPresentation(){if(!document.body.classList.contains('presentation-mode'))return;let frame=document.querySelector('.app-frame');if(!frame)return;frame.style.zoom='1';requestAnimationFrame(()=>{let vw=window.innerWidth||document.documentElement.clientWidth,vh=window.innerHeight||document.documentElement.clientHeight;let w=Math.max(frame.scrollWidth,frame.getBoundingClientRect().width),h=Math.max(frame.scrollHeight,frame.getBoundingClientRect().height);let scale=Math.min(1,vw/Math.max(1,w),vh/Math.max(1,h));if(scale<.995)frame.style.zoom=String(Math.max(.68,scale));else frame.style.zoom='1'})}
async function presentation(){if(route.center!=='operations')return;if(document.body.classList.contains('screenshot-mode'))exitScreenshot();presentationRestore={livePaused,snapshotPaused};livePaused=false;snapshotPaused=false;presentationActive=true;document.body.classList.add('presentation-mode');let x=document.querySelector('#exitScreenshot');x.classList.add('hidden');try{if(!document.fullscreenElement&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen()}catch(e){}window.scrollTo(0,0);render();requestAnimationFrame(()=>requestAnimationFrame(fitPresentation))}
function exitPresentation(){presentationActive=false;document.body.classList.remove('presentation-mode');let frame=document.querySelector('.app-frame');if(frame)frame.style.zoom='';if(presentationRestore){livePaused=!!presentationRestore.livePaused;snapshotPaused=!!presentationRestore.snapshotPaused;presentationRestore=null}document.querySelector('#exitScreenshot').classList.add('hidden');document.querySelector('#screenshotReportTitle')?.remove();if(document.fullscreenElement&&document.exitFullscreen){try{document.exitFullscreen()}catch(e){}}render()}
function exitDisplayMode(){if(document.body.classList.contains('presentation-mode'))return exitPresentation();return exitScreenshot()}
