function bindInputs(){document.querySelectorAll('input,select,textarea').forEach(x=>x.addEventListener('input',()=>{if(mode!=='view')dirty=true}));let code=document.querySelector('#tf-code');if(code)code.onchange=()=>{dirty=true;collectToolForm(draft);draft.codename=code.value;let models=PRODUCT_CATALOG[draft.codename]||[];draft.model=models.length?models[0]:(draft.model||'TBD');draft.currentChecklist=firstChecklist(draft);draft.microSchedule=firstChecklist(draft);render()};let add=document.querySelector('#addNc');if(add)add.onclick=()=>{collectToolForm(draft);draft.ncs.push({id:'',description:'',state:'Open',days:0,blocking:false,poa:'',owner:'',opened:today()});dirty=true;render()};document.querySelectorAll('[data-remove-nc]').forEach(b=>b.onclick=()=>{collectToolForm(draft);draft.ncs.splice(Number(b.dataset.removeNc),1);dirty=true;render()});let g=document.querySelector('#globalSearch');if(g){g.value=window.__b7Search||'';let run=()=>{let q=g.value.toLowerCase().trim(),out=[];window.__b7Search=g.value;if(q){state.tools.forEach(t=>{if(JSON.stringify(t).toLowerCase().includes(q))out.push(`<div class="search-result" role="button" tabindex="0" data-search-tool="${esc(t.id)}" onclick="event.stopPropagation();window.B7Core.openTool(this.dataset.searchTool);return false"><b>TOOL ${esc(t.id)}</b> · ${esc(t.codename)} · ${esc(t.customer)} · ${esc(t.toolStatus)}</div>`)});state.meetings.forEach(m=>{if(JSON.stringify(m).toLowerCase().includes(q))out.push(`<div class="search-result" role="button" tabindex="0" data-search-meeting="${esc(m.id)}"><b>MEETING</b> · ${esc(m.type)} · ${esc(m.tool||fmtDate(m.date)||'')}</div>`)});state.actions.forEach(a=>{if(JSON.stringify(a).toLowerCase().includes(q))out.push(`<div class="search-result" role="button" tabindex="0" data-search-action="${esc(a.id)}"><b>ACTION</b> · ${esc(a.text)}</div>`)});state.references.forEach(r=>{if(JSON.stringify(r).toLowerCase().includes(q))out.push(`<div class="search-result" role="button" tabindex="0" data-search-ref="${esc(r.id)}"><b>REFERENCE</b> · ${esc(r.title)}</div>`)})}document.querySelector('#searchResults').innerHTML=out.join('')||(q?'<p>No results.</p>':'')};g.oninput=run;run()}let pa=document.querySelector('#priorityAnchor');if(pa)pa.onchange=()=>{state.priorityMeta[route.sub].anchor=pa.value;dirty=true;let t=document.querySelector('#priorityRangeTitle');if(t)t.textContent=priorityTitle(route.sub)};let rs=document.querySelector('#refSearch');if(rs)rs.oninput=()=>{let q=rs.value.toLowerCase();document.querySelectorAll('.ref-row').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none')};let ah=document.querySelector('#actionHistorySearch');if(ah)ah.oninput=()=>{let q=ah.value.toLowerCase();document.querySelectorAll('.action-list .action-card').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none')};let f=document.querySelector('#importFile');if(f)f.onchange=async()=>{try{state=normalize(JSON.parse(await f.files[0].text()));saveState('JSON DATA IMPORTED');render()}catch(e){alert('Import failed: '+e.message)}}}

// V4.2 hard routing bridge. Inline card/button handlers call this object directly,
// then the editor functions re-assert their state on the next event-loop tick. This prevents
// any legacy delegated navigation handler from switching to Update Center and clearing the
// selected tool/create mode afterwards.
window.B7Core={
  openTool:(id)=>openTool(String(id||'')),
  addTool:()=>addTool(),
  saveTool:()=>saveCurrent(),
  cancelTool:()=>cancelEdit()
};

// V4.1 direct bindings for the two highest-priority workflows.
// These are intentionally attached after every render so Add Tool and Tool Edit do not
// depend on delegated navigation state.  They stop propagation before the document-level
// handlers can switch centers without preserving the selected tool/editor mode.
function bindCoreInteractions(){
  document.querySelectorAll('#pageActions [data-act="addTool"]').forEach(btn=>{
    btn.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();addTool();},{capture:true});
  });
  document.querySelectorAll('[data-open-tool],[data-tool],[data-search-tool],[data-alert-tool]').forEach(el=>{
    if(el.matches('button,input,select,textarea,a'))return;
    el.addEventListener('click',e=>{
      // Embedded controls such as VIEW ALL must keep their own action.
      if(e.target.closest('button,input,select,textarea,a,[data-fi-checklists],[data-lead-tasks],[data-carousel]'))return;
      const id=el.dataset.openTool||el.dataset.tool||el.dataset.searchTool||el.dataset.alertTool;
      if(!id)return;
      e.preventDefault();e.stopImmediatePropagation();openTool(id);
    },{capture:true});
    el.addEventListener('keydown',e=>{
      if(!['Enter',' '].includes(e.key))return;
      const id=el.dataset.openTool||el.dataset.tool||el.dataset.searchTool||el.dataset.alertTool;
      if(!id)return;
      e.preventDefault();e.stopImmediatePropagation();openTool(id);
    },{capture:true});
  });
}

document.addEventListener('click',e=>{const b=e.target.closest('[data-main-presentation]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(route.center!=='operations'||route.sub!=='live'){route={center:'operations',sub:'live'};mode='view';render()}presentation();},{capture:true});
document.addEventListener('click',e=>{const btn=e.target.closest('#mainNav button[data-center]');if(!btn)return;e.preventDefault();e.stopImmediatePropagation();go(btn.dataset.center);},{capture:true});
// Stable core navigation: tool/status cards are first-class drill-down targets.
document.addEventListener('click',e=>{
  const interactive=e.target.closest('button,select,input,textarea,a');
  if(interactive)return;
  const toolTarget=e.target.closest('[data-open-tool],[data-tool],[data-search-tool],[data-alert-tool]');
  if(toolTarget){
    const id=toolTarget.dataset.openTool||toolTarget.dataset.tool||toolTarget.dataset.searchTool||toolTarget.dataset.alertTool;
    if(id){e.preventDefault();e.stopPropagation();openTool(id);return;}
  }
  const source=e.target.closest('[data-source-center]');
  if(source){e.preventDefault();e.stopPropagation();go(source.dataset.sourceCenter,source.dataset.sourceSub||undefined);}
},true);
document.addEventListener('keydown',e=>{
  if(!['Enter',' '].includes(e.key))return;
  const el=e.target.closest('[data-open-tool],[data-tool],[data-search-tool],[data-alert-tool],[data-source-center]');
  if(!el)return;
  e.preventDefault();
  const id=el.dataset.openTool||el.dataset.tool||el.dataset.searchTool||el.dataset.alertTool;
  if(id)return openTool(id);
  if(el.dataset.sourceCenter)return go(el.dataset.sourceCenter,el.dataset.sourceSub||undefined);
});
